PHASE_INC = {chess.PAWN:0, chess.KNIGHT:1, chess.BISHOP:1, chess.ROOK:2, chess.QUEEN:4, chess.KING:0}

# Precompute [color][piece][square] -> (mg, eg)
MG = {}
EG = {}
for pt in chess.PIECE_TYPES:
    for sq in chess.SQUARES:
        # tables are listed from a8..h8 first (rank 8) so index for white = sq ^ 56
        MG[(chess.WHITE, pt, sq)] = MG_VAL[pt] + MG_T[pt][sq ^ 56]
        EG[(chess.WHITE, pt, sq)] = EG_VAL[pt] + EG_T[pt][sq ^ 56]
        MG[(chess.BLACK, pt, sq)] = MG_VAL[pt] + MG_T[pt][sq]
        EG[(chess.BLACK, pt, sq)] = EG_VAL[pt] + EG_T[pt][sq]

MATE = 100000

def evaluate(board):
    """Return score from side-to-move perspective."""
    mg = 0; eg = 0; phase = 0
    pm = board.piece_map()
    for sq, p in pm.items():
        if p.color == chess.WHITE:
            mg += MG[(chess.WHITE, p.piece_type, sq)]
            eg += EG[(chess.WHITE, p.piece_type, sq)]
        else:
            mg -= MG[(chess.BLACK, p.piece_type, sq)]
            eg -= EG[(chess.BLACK, p.piece_type, sq)]
        phase += PHASE_INC[p.piece_type]
    if phase > 24: phase = 24
    score = (mg * phase + eg * (24 - phase)) // 24
    # small bonuses: bishop pair
    wb = len(board.pieces(chess.BISHOP, chess.WHITE)); bb = len(board.pieces(chess.BISHOP, chess.BLACK))
    if wb >= 2: score += 30
    if bb >= 2: score -= 30
    # passed / doubled pawns quick eval
    wp = board.pieces(chess.PAWN, chess.WHITE); bp = board.pieces(chess.PAWN, chess.BLACK)
    for f in range(8):
        fm = chess.BB_FILES[f]
        wc = chess.popcount(wp & fm); bc = chess.popcount(bp & fm)
        if wc > 1: score -= 15 * (wc - 1)
        if bc > 1: score += 15 * (bc - 1)
    return score if board.turn == chess.WHITE else -score

PV = {chess.PAWN:1, chess.KNIGHT:3, chess.BISHOP:3, chess.ROOK:5, chess.QUEEN:9, chess.KING:20}

class Searcher:
    def __init__(self):
        self.tt = {}
        self.nodes = 0
        self.killers = {}
        self.history = {}
        self.stop = False
        self.deadline = 0

    def check_time(self):
        if (self.nodes & 1023) == 0 and time.time() > self.deadline:
            self.stop = True

    def order_moves(self, board, moves, tt_move, ply):
        scored = []
        killers = self.killers.get(ply, ())
        for m in moves:
            s = 0
            if m == tt_move:
                s = 1000000
            elif board.is_capture(m):
                victim = board.piece_type_at(m.to_square)
                if victim is None: victim = chess.PAWN  # en passant
                attacker = board.piece_type_at(m.from_square)
                s = 100000 + PV[victim] * 10 - PV[attacker]
            elif m.promotion:
                s = 90000
            elif m in killers:
                s = 80000
            else:
                s = self.history.get((board.turn, m.from_square, m.to_square), 0)
            scored.append((s, m))
        scored.sort(key=lambda x: -x[0])
        return [m for s, m in scored]

    def quiesce(self, board, alpha, beta, depth=0):
        self.nodes += 1
        self.check_time()
        stand = evaluate(board)
        if stand >= beta:
            return stand
        if alpha < stand:
            alpha = stand
        if depth > 6:
            return stand
        moves = [m for m in board.legal_moves if board.is_capture(m) or m.promotion]
        # order by MVV-LVA
        def key(m):
            v = board.piece_type_at(m.to_square) or chess.PAWN
            a = board.piece_type_at(m.from_square)
            return -(PV[v]*10 - PV[a])
        moves.sort(key=key)
        for m in moves:
            # delta pruning
            v = board.piece_type_at(m.to_square)
            gain = (MG_VAL[v] if v else 100) + (900 if m.promotion else 0)
            if stand + gain + 200 < alpha:
                continue
            board.push(m)
            score = -self.quiesce(board, -beta, -alpha, depth+1)
            board.pop()
            if self.stop: return alpha
            if score >= beta:
                return score
            if score > alpha:
                alpha = score
        return alpha

    def search(self, board, depth, alpha, beta, ply, null_ok=True):
        self.nodes += 1
        self.check_time()
        if self.stop: return 0
        if ply > 0 and (board.is_repetition(2) or board.halfmove_clock >= 100):
            return 0
        if board.is_insufficient_material():
            return 0
        in_check = board.is_check()
        if in_check:
            depth += 1  # check extension
        if depth <= 0:
            return self.quiesce(board, alpha, beta)
        key = board._transposition_key()
        tt_move = None
        ent = self.tt.get(key)
        if ent is not None:
            tdepth, tscore, tflag, tmove = ent
            tt_move = tmove
            if tdepth >= depth and ply > 0:
                if tflag == 0: return tscore
                if tflag == 1 and tscore >= beta: return tscore
                if tflag == 2 and tscore <= alpha: return tscore
        # null move pruning
        if null_ok and not in_check and depth >= 3 and ply > 0:
            # ensure non-pawn material
            if board.occupied_co[board.turn] & ~(board.pawns | board.kings):
                board.push(chess.Move.null())
                score = -self.search(board, depth - 3, -beta, -beta + 1, ply + 1, False)
                board.pop()
                if self.stop: return 0
                if score >= beta:
                    return beta
        moves = list(board.legal_moves)
        if not moves:
            if in_check: return -MATE + ply
            return 0
        moves = self.order_moves(board, moves, tt_move, ply)
        best = -MATE - 1
        best_move = None
        orig_alpha = alpha
        for i, m in enumerate(moves):
            board.push(m)
            gives_check = board.is_check()
            reduce = 0
            if i >= 4 and depth >= 3 and not in_check and not gives_check and not board.is_capture(m) and not m.promotion:
                reduce = 1
            if reduce:
                score = -self.search(board, depth - 1 - reduce, -alpha - 1, -alpha, ply + 1)
                if score > alpha and not self.stop:
                    score = -self.search(board, depth - 1, -beta, -alpha, ply + 1)
            else:
                score = -self.search(board, depth - 1, -beta, -alpha, ply + 1)
            board.pop()
            if self.stop: return 0
            if score > best:
                best = score
                best_move = m
            if score > alpha:
                alpha = score
            if alpha >= beta:
                if not board.is_capture(m):
                    k = self.killers.setdefault(ply, [])
                    if m not in k:
                        k.insert(0, m)
                        if len(k) > 2: k.pop()
                    hk = (board.turn, m.from_square, m.to_square)
                    self.history[hk] = self.history.get(hk, 0) + depth * depth
                break
        flag = 0
        if best <= orig_alpha: flag = 2
        elif best >= beta: flag = 1
        self.tt[key] = (depth, best, flag, best_move)
        return best

    def best_move(self, board, time_limit=10.0, max_depth=20):
        self.deadline = time.time() + time_limit
        self.stop = False
        self.nodes = 0
        self.killers = {}
        best = None
        best_score = 0
        moves = list(board.legal_moves)
        if len(moves) == 1:
            return moves[0], 0, 1
        start = time.time()
        for depth in range(1, max_depth + 1):
            alpha = -MATE - 1; beta = MATE + 1
            # aspiration windows
            if depth >= 4:
                alpha = best_score - 50; beta = best_score + 50
            while True:
                score = self.search(board, depth, alpha, beta, 0)
                if self.stop: break
                if score <= alpha:
                    alpha = -MATE - 1
                elif score >= beta:
                    beta = MATE + 1
                else:
                    break
            if self.stop:
                break
            ent = self.tt.get(board._transposition_key())
            if ent and ent[3] is not None:
                best = ent[3]
                best_score = score
            el = time.time() - start
            print(f"depth {depth} score {best_score} best {best} nodes {self.nodes} time {el:.1f}", file=sys.stderr)
            if abs(best_score) > MATE - 1000:
                break
            if el > time_limit * 0.4:
                break
        if best is None:
            best = moves[0]
        return best, best_score, depth

